/* exposed for the renderer + tests (the metric constants and the
 * glyph lookup; non-printable/out-of-range codes answer nullptr -
 * the renderer renders a blank cell for them) */
const unsigned char* thumbnail_font_glyph(unsigned int code) {
    if (code < unsigned(kFontFirst) || code > unsigned(kFontLast))
        return nullptr;
    return kGlyphs[code - unsigned(kFontFirst)];
}

unsigned thumbnail_font_cell_w() { return unsigned(kFontW); }
unsigned thumbnail_font_cell_h() { return unsigned(kFontH); }

